import { test } from 'node:test';
import assert from 'node:assert/strict';
import status from '../vscode/status-core.js';

const now = 1_000_000_000;
const stuckMs = 10 * 60_000;
const id = '7fa97870-6578-4ed2-b7c9-1dc4c9a2ef09';

const at = (secondsAgo, event, extra = {}) => ({ t: now - secondsAgo * 1000, event, ...extra });
const stateOf = (events) => status.sessionState({ id, events: [...events].sort((first, second) => first.t - second.t), now, stuckMs });

test('a fresh session is idle and named after its title, else its folder', () => {
  assert.equal(stateOf([at(60, 'SessionStart', { title: 'portal-tester', folder: 'rehlko-portal' })]).name, 'portal-tester');

  const session = stateOf([at(60, 'SessionStart', { folder: 'rehlko-portal' })]);

  assert.equal(session.name, 'rehlko-portal');
  assert.equal(session.status, 'idle');
});

test('a prompt and its tools mean working, with the current tool', () => {
  const session = stateOf([
    at(90, 'SessionStart'),
    at(60, 'UserPromptSubmit', { promptId: 'p1' }),
    at(30, 'PostToolUse', { promptId: 'p1', tool: 'Bash' }),
  ]);

  assert.equal(session.status, 'working');
  assert.equal(session.tool, 'Bash');
  assert.equal(session.since, now - 60_000);
});

test('a permission request waits for the developer, and the next tool result returns to working', () => {
  const waiting = [at(60, 'UserPromptSubmit', { promptId: 'p1' }), at(40, 'PermissionRequest', { promptId: 'p1', tool: 'Edit' })];

  assert.equal(stateOf(waiting).status, 'permission');
  assert.equal(stateOf([...waiting, at(10, 'PostToolUse', { promptId: 'p1', tool: 'Edit' })]).status, 'working');
});

test('AskUserQuestion and asking stops wait for an answer; other stops need review', () => {
  assert.equal(stateOf([at(60, 'UserPromptSubmit', { promptId: 'p1' }), at(5, 'PreToolUse', { promptId: 'p1', tool: 'AskUserQuestion' })]).status, 'question');
  assert.equal(stateOf([at(60, 'UserPromptSubmit', { promptId: 'p1' }), at(5, 'Stop', { promptId: 'p1', asks: true, last: 'Which one?' })]).status, 'question');

  const finished = stateOf([at(60, 'UserPromptSubmit', { promptId: 'p1' }), at(5, 'Stop', { promptId: 'p1', asks: false, last: 'All tests pass.' })]);

  assert.equal(finished.status, 'finished');
  assert.equal(finished.last, 'All tests pass.');
});

test('a tool event of a turn recorded after its stop does not reopen it', () => {
  const session = stateOf([
    at(60, 'UserPromptSubmit', { promptId: 'p1' }),
    at(20, 'Stop', { promptId: 'p1', asks: false, last: 'Done.' }),
    at(19, 'PostToolUse', { promptId: 'p1', tool: 'Bash' }),
  ]);

  assert.equal(session.status, 'finished');
});

test('late events of an earlier turn do not change the current one', () => {
  const session = stateOf([
    at(60, 'UserPromptSubmit', { promptId: 'p1' }),
    at(30, 'UserPromptSubmit', { promptId: 'p2' }),
    at(20, 'PermissionRequest', { promptId: 'p1', tool: 'Bash' }),
  ]);

  assert.equal(session.status, 'working');
});

test('a working session without events past the threshold is possibly stuck, keeping its tool', () => {
  const session = stateOf([at(1200, 'UserPromptSubmit', { promptId: 'p1' }), at(700, 'PostToolUse', { promptId: 'p1', tool: 'Bash' })]);

  assert.equal(session.status, 'stuck');
  assert.equal(session.tool, 'Bash');
  assert.equal(status.cardDescription(session, now), 'possibly stuck · after Bash · 11m');
  assert.equal(status.cardDescription({ status: 'permission', tool: 'Edit', since: now - 5000 }, now), 'waiting for permission · Edit · 5s');
  assert.equal(status.cardDescription({ status: 'finished', tool: 'Bash', since: now - 5000 }, now), 'finished, needs review · 5s');
  assert.equal(stateOf([at(1200, 'UserPromptSubmit', { promptId: 'p1' }), at(500, 'PostToolUse', { promptId: 'p1', tool: 'Bash' })]).status, 'working');
});

test('unreadable lines are skipped and lines are ordered by time', () => {
  const events = status.parseEvents('{"t":2,"event":"Stop"}\nnot json\n\n{"t":1,"event":"SessionStart"}\n{"event":"NoTime"}\n');

  assert.deepEqual(events.map((event) => event.event), ['SessionStart', 'Stop']);
});

test('cards are sorted with waiting sessions first, longest waiting first, then stuck, finished, working, idle', () => {
  const card = (name, sessionStatus, since) => ({ name, status: sessionStatus, since });
  const sorted = [
    card('idle', 'idle', 1),
    card('working', 'working', 1),
    card('question-new', 'question', 50),
    card('finished', 'finished', 1),
    card('permission-old', 'permission', 10),
    card('stuck', 'stuck', 1),
  ].sort(status.byUrgency);

  assert.deepEqual(sorted.map((session) => session.name), ['permission-old', 'question-new', 'stuck', 'finished', 'working', 'idle']);
  assert.equal(status.waitingCount(sorted), 2);
});

test('sessions are grouped by project, the most urgent project first, each sorted by urgency', () => {
  const card = (name, project, sessionStatus, since) => ({ name, project, status: sessionStatus, since });
  const groups = status.groupByProject([
    card('api-worker', 'api', 'working', 5),
    card('portal-idle', 'rehlko-portal', 'idle', 1),
    card('portal-asks', 'rehlko-portal', 'question', 20),
    card('api-done', 'api', 'finished', 3),
    card('portal-perm', 'rehlko-portal', 'permission', 10),
  ]);

  assert.deepEqual(groups.map((group) => group.project), ['rehlko-portal', 'api']);
  assert.deepEqual(groups[0].sessions.map((session) => session.name), ['portal-perm', 'portal-asks', 'portal-idle']);
  assert.deepEqual(groups[1].sessions.map((session) => session.name), ['api-done', 'api-worker']);
  assert.equal(groups[0].top.name, 'portal-perm');
  assert.equal(status.groupDescription(groups[0]), '2 waiting · 3 sessions');
  assert.equal(status.groupDescription({ sessions: [card('a', 'x', 'working', 1)], waiting: 0 }), '1 session');
});

test('a session takes its project from the first folder recorded, or a placeholder', () => {
  assert.equal(stateOf([at(60, 'UserPromptSubmit', { promptId: 'p1', folder: 'rehlko-portal' })]).project, 'rehlko-portal');
  assert.equal(stateOf([
    at(90, 'SessionStart', { folder: 'rehlko-portal', title: 'rehlko-portal-coordinator' }),
    at(60, 'UserPromptSubmit', { promptId: 'p1', folder: '.coord' }),
  ]).project, 'rehlko-portal');
  assert.equal(stateOf([at(60, 'PostToolUse', { promptId: 'p1', tool: 'Bash' })]).project, 'unknown project');
});

test('only the latest session per title is kept; untitled sessions are never merged', () => {
  const session = (sessionId, name, titled, lastEventAt) => ({ id: sessionId, name, titled, lastEventAt });
  const kept = status.latestPerTitle([
    session('old', 'rehlko-portal-coordinator', true, 100),
    session('new', 'rehlko-portal-coordinator', true, 200),
    session('tester', 'rehlko-portal-tester', true, 50),
    session('plain-1', 'rehlko-portal', false, 10),
    session('plain-2', 'rehlko-portal', false, 20),
  ]);

  assert.deepEqual(kept.map((entry) => entry.id), ['new', 'tester', 'plain-1', 'plain-2']);
});

test('a titled session reports it, a folder-named one does not', () => {
  assert.equal(stateOf([at(60, 'SessionStart', { title: 'portal-tester', folder: 'portal' })]).titled, true);
  assert.equal(stateOf([at(60, 'SessionStart', { folder: 'portal' })]).titled, false);
});

test('waiting sessions come in urgency order and the next one wraps around', () => {
  const session = (id, sessionStatus, since) => ({ id, status: sessionStatus, since });
  const waiting = status.waitingSessions([
    session('working', 'working', 1),
    session('question-new', 'question', 30),
    session('permission-old', 'permission', 10),
    session('finished', 'finished', 1),
  ]);

  assert.deepEqual(waiting.map((entry) => entry.id), ['permission-old', 'question-new']);
  assert.equal(status.nextWaiting(waiting, undefined).id, 'permission-old');
  assert.equal(status.nextWaiting(waiting, 'permission-old').id, 'question-new');
  assert.equal(status.nextWaiting(waiting, 'question-new').id, 'permission-old');
  assert.equal(status.nextWaiting(waiting, 'gone').id, 'permission-old');
  assert.equal(status.nextWaiting([], 'permission-old'), undefined);
});

test('a click shows an own tab, raises another window, or explains', () => {
  assert.equal(status.clickAction({ kind: 'here' }), 'show');
  assert.equal(status.clickAction({ kind: 'other', window: { pid: 2 } }), 'raise');
  assert.equal(status.clickAction({ kind: 'none' }), 'message');
});

test('a session reports the latest Claude process id it recorded', () => {
  assert.equal(stateOf([at(90, 'SessionStart', { pid: 100 }), at(60, 'UserPromptSubmit', { promptId: 'p1', pid: 100 })]).pid, 100);
  assert.equal(stateOf([at(90, 'SessionStart')]).pid, undefined);
});

test('after /resume or /clear only the newest session of a process is kept; sessions without pid are untouched', () => {
  const session = (id, pid, lastEventAt) => ({ id, pid, lastEventAt });
  const kept = status.latestPerProcess([
    session('backoffices-claude', 7, 100),
    session('test-chat', 7, 200),
    session('other-tab', 8, 50),
    session('old-a', undefined, 10),
    session('old-b', undefined, 20),
  ]);

  assert.deepEqual(kept.map((entry) => entry.id), ['test-chat', 'other-tab', 'old-a', 'old-b']);
});

test('sessions whose Claude process ended are dropped; sessions without a process id stay', () => {
  const sessions = [{ id: 'live', pid: 1 }, { id: 'closed', pid: 2 }, { id: 'old', pid: undefined }];

  assert.deepEqual(status.dropEnded(sessions, (pid) => pid === 1).map((session) => session.id), ['live', 'old']);
});

test('order pruning drops ids of sessions that no longer exist and keeps titled names', () => {
  const sessions = [{ id: 'a' }, { id: 'b' }];

  assert.deepEqual(status.pruneOrderKeys(['id:a', 'rehlko-portal-tester', 'id:gone', 'id:b', 'api-coordinator'], sessions), ['id:a', 'rehlko-portal-tester', 'id:b', 'api-coordinator']);
});

test('a plain tab is renamed to the session now running in its process, and only then', () => {
  const sessions = [{ name: 'test-chat', pid: 7 }, { name: 'api-coordinator', pid: 9 }];

  assert.equal(status.plainTabRename('claude', 7, sessions), 'test-chat');
  assert.equal(status.plainTabRename('test-chat', 7, sessions), null);
  assert.equal(status.plainTabRename('claude', 99, sessions), null);
  assert.equal(status.plainTabRename('claude', undefined, sessions), null);
});

test('a session is located by its process first, then by name', () => {
  const windows = [
    { pid: 10, folder: 'P:\\repos\\Rehlko\\backoffices', sessions: ['backoffices-claude'], pids: [7] },
    { pid: 20, folder: 'P:\\repos\\Rehlko\\api', sessions: ['api-coordinator'], pids: [9] },
  ];

  assert.equal(status.sessionLocation('test-chat', 10, windows, 7).kind, 'here');
  assert.equal(status.sessionLocation('test-chat', 20, windows, 7).window.pid, 10);
  assert.equal(status.sessionLocation('api-coordinator', 10, windows, undefined).window.pid, 20);
  assert.equal(status.sessionLocation('test-chat', 10, windows, 99).kind, 'none');
  assert.equal(status.sessionLocation('api-coordinator', 10, [{ pid: 20, folder: 'x', sessions: ['api-coordinator'] }], 9).window.pid, 20);
});

test('only well-formed entries of running windows count', () => {
  const entries = [
    { pid: 10, folder: 'P:\\repos\\Rehlko\\rehlko-portal', sessions: ['rehlko-portal-coordinator'] },
    { pid: 20, folder: 'P:\\repos\\Rehlko\\api', sessions: ['api-coordinator'] },
    { pid: 30, folder: 'P:\\repos\\gone', sessions: [] },
    { pid: '40', folder: 'x', sessions: [] },
    { pid: 50, sessions: [] },
    null,
  ];

  assert.deepEqual(status.liveWindows(entries, (pid) => pid !== 30).map((entry) => entry.pid), [10, 20]);
});

test('a session is located in this window, another window, or none', () => {
  const windows = [
    { pid: 10, folder: 'P:\\repos\\Rehlko\\rehlko-portal', sessions: ['rehlko-portal-coordinator', 'rehlko-portal-tester'] },
    { pid: 20, folder: 'P:\\repos\\Rehlko\\api', sessions: ['api-coordinator'] },
  ];
  const here = status.sessionLocation('rehlko-portal-tester', 10, windows);
  const other = status.sessionLocation('api-coordinator', 10, windows);
  const none = status.sessionLocation('vs-code skill upgrade', 10, windows);

  assert.equal(here.kind, 'here');
  assert.equal(other.kind, 'other');
  assert.equal(other.window.pid, 20);
  assert.equal(none.kind, 'none');
  assert.equal(status.locationLabel(here), 'in this window');
  assert.equal(status.locationLabel(other), 'in window api');
  assert.equal(status.locationLabel({ kind: 'other', window: { folder: '/home/dev/app/' } }), 'in window app');
  assert.equal(status.locationLabel(none), 'not in a toolkit tab');
});

test('durations read as seconds, minutes, then hours and minutes', () => {
  assert.equal(status.formatDuration(45_000), '45s');
  assert.equal(status.formatDuration(12 * 60_000), '12m');
  assert.equal(status.formatDuration((2 * 60 + 5) * 60_000), '2h 05m');
  assert.equal(status.formatDuration(-5), '0s');
});

test('hidden sessions are split out, newest first, and come back with a newer event', () => {
  const sessions = [
    { id: 'a', lastEventAt: 100 },
    { id: 'b', lastEventAt: 300 },
    { id: 'c', lastEventAt: 200 },
    { id: 'd', lastEventAt: 500 },
  ];
  const { visible, hidden } = status.splitHidden(sessions, { b: 300, c: 200, d: 400 });

  assert.deepEqual(visible.map((session) => session.id), ['a', 'd']);
  assert.deepEqual(hidden.map((session) => session.id), ['b', 'c']);
  assert.deepEqual(status.splitHidden(sessions, {}).hidden, []);
});

test('placed items keep the stored order, the rest follow by the fallback', () => {
  const items = ['idle', 'waiting', 'working', 'new'].map((name) => ({ name }));
  const ordered = status.applyOrder(items, ['working', 'idle', 'gone'], (item) => item.name, (first, second) => first.name.localeCompare(second.name));

  assert.deepEqual(ordered.map((item) => item.name), ['working', 'idle', 'new', 'waiting']);
  assert.deepEqual(status.applyOrder(items, [], (item) => item.name, () => 0).map((item) => item.name), ['idle', 'waiting', 'working', 'new']);
});

test('moving a key places it before the target, or last without one', () => {
  assert.deepEqual(status.moveBefore(['a', 'b', 'c', 'd'], 'd', 'b'), ['a', 'd', 'b', 'c']);
  assert.deepEqual(status.moveBefore(['a', 'b', 'c'], 'a', 'c'), ['b', 'a', 'c']);
  assert.deepEqual(status.moveBefore(['a', 'b', 'c'], 'a', undefined), ['b', 'c', 'a']);
  assert.deepEqual(status.moveBefore(['a', 'b'], 'x', 'b'), ['a', 'x', 'b']);
  assert.deepEqual(status.moveBefore(['a', 'b'], 'a', 'missing'), ['b', 'a']);
});

test('the developer order wins over urgency for projects and sessions; unplaced ones follow by urgency', () => {
  const card = (name, project, sessionStatus, since) => ({ name, titled: true, project, status: sessionStatus, since });
  const groups = status.groupByProject([
    card('portal-idle', 'rehlko-portal', 'idle', 1),
    card('portal-asks', 'rehlko-portal', 'question', 5),
    card('portal-new', 'rehlko-portal', 'permission', 9),
    card('api-work', 'api', 'working', 2),
    card('web-done', 'web', 'finished', 3),
  ]);
  const ordered = status.orderedGroups(groups, {
    projects: ['api', 'rehlko-portal'],
    sessions: { 'rehlko-portal': ['portal-idle', 'portal-asks'] },
  });

  assert.deepEqual(ordered.map((group) => group.project), ['api', 'rehlko-portal', 'web']);
  assert.deepEqual(ordered[1].sessions.map((session) => session.name), ['portal-idle', 'portal-asks', 'portal-new']);
  assert.deepEqual(status.orderedGroups(groups, {}).map((group) => group.project), ['rehlko-portal', 'web', 'api']);
});

test('a reorder keeps placed items that are not displayed, next to their stored neighbour', () => {
  assert.deepEqual(status.mergeOrder(['b', 'a'], ['a', 'x', 'b', 'y']), ['b', 'y', 'a', 'x']);
  assert.deepEqual(status.mergeOrder(['a', 'b'], ['gone', 'a']), ['gone', 'a', 'b']);
  assert.deepEqual(status.mergeOrder(['a'], []), ['a']);
  assert.deepEqual(status.moveBefore(status.mergeOrder(['b', 'a'], ['a', 'hidden', 'b']), 'b', 'a'), ['b', 'a', 'hidden']);
});

test('titled sessions are keyed by name, untitled ones by id, so twins never move together', () => {
  const twins = [
    { id: 'one', name: 'rehlko-portal', titled: false, status: 'working', since: 1 },
    { id: 'two', name: 'rehlko-portal', titled: false, status: 'working', since: 2 },
    { id: 'three', name: 'rehlko-portal-tester', titled: true, status: 'working', since: 3 },
  ];

  assert.deepEqual(twins.map(status.sessionKey), ['id:one', 'id:two', 'rehlko-portal-tester']);

  const keys = status.moveBefore(twins.map(status.sessionKey), 'id:two', 'id:one');
  const [group] = status.orderedGroups([{ project: 'rehlko-portal', sessions: twins, top: twins[0] }], { sessions: { 'rehlko-portal': keys } });

  assert.deepEqual(group.sessions.map((session) => session.id), ['two', 'one', 'three']);
});

test('one step up or down targets the right neighbour, and the ends do nothing', () => {
  const keys = ['a', 'b', 'c'];

  assert.equal(status.stepTarget(keys, 'b', -1), 'a');
  assert.equal(status.stepTarget(keys, 'a', 1), 'c');
  assert.equal(status.stepTarget(keys, 'b', 1), undefined);
  assert.equal(status.stepTarget(keys, 'a', -1), null);
  assert.equal(status.stepTarget(keys, 'c', 1), null);
  assert.equal(status.stepTarget(keys, 'x', 1), null);
  assert.deepEqual(status.moveBefore(keys, 'b', status.stepTarget(keys, 'b', 1)), ['a', 'c', 'b']);
  assert.deepEqual(status.moveBefore(keys, 'c', status.stepTarget(keys, 'c', -1)), ['a', 'c', 'b']);
});

test('hidden entries of unreadable files are kept', () => {
  const sessions = [{ id: 'a', lastEventAt: 100 }];

  assert.deepEqual(status.pruneHidden({ a: 100, flaky: 50, gone: 10 }, sessions, new Set(['flaky'])), { a: 100, flaky: 50 });
});

test('pruning keeps only hidden entries of existing sessions without newer events', () => {
  const sessions = [{ id: 'a', lastEventAt: 100 }, { id: 'b', lastEventAt: 300 }];

  assert.deepEqual(status.pruneHidden({ a: 100, b: 200, gone: 50 }, sessions), { a: 100 });
  assert.deepEqual(status.pruneHidden({}, sessions), {});
});

test('a hidden card comes back only with a newer event', () => {
  assert.equal(status.isVisible({ lastEventAt: 100 }, undefined), true);
  assert.equal(status.isVisible({ lastEventAt: 100 }, 100), false);
  assert.equal(status.isVisible({ lastEventAt: 101 }, 100), true);
});

test('every status has a label and a theme colour', () => {
  for (const [name, look] of Object.entries(status.STATUS)) {
    assert.match(look.label, /\w/, name);
    assert.match(look.color, /^[a-zA-Z.]+$/, name);
  }
});

const vscode = require('vscode');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const status = require('./status-core');
const registry = require('./registry');
const sessionFiles = require('./session-files');

const VIEW_ID = 'claudeToolkit.sessions';
const STALE_MS = 6 * 3_600_000;
const REFRESH_MS = 15_000;
const HIDDEN_SESSIONS = 'hiddenSessions';
const SESSION_ORDER = 'sessionOrder';
const DRAG_MIME = 'application/vnd.code.tree.claudetoolkit.sessions';

const statusDir = () => path.join(os.homedir(), '.agent-status');
const sessionsDir = () => path.join(statusDir(), 'sessions');
const windowsDir = () => path.join(statusDir(), 'windows');
const focusDir = () => path.join(statusDir(), 'focus');
const ownWindowFile = () => path.join(windowsDir(), `${process.pid}.json`);
const focusFile = (pid) => path.join(focusDir(), `${pid}.json`);

const writeFocusRequest = (windowPid, session) => registry.writeAtomically(focusFile(windowPid), JSON.stringify({ session: session.name, pid: session.pid, at: Date.now() }));

const isAlive = (pid) => {
  try {
    process.kill(pid, 0);

    return true;
  } catch (error) {
    return error.code === 'EPERM';
  }
};

const readSessions = (now, stuckMs) => {
  const { readable, unreadableIds } = sessionFiles.readSessionFiles(sessionsDir());
  const sessions = readable
    .map(({ id, events }) => status.sessionState({ id, events, now, stuckMs }))
    .filter((session) => now - session.lastEventAt <= STALE_MS);

  return { sessions, unreadableIds };
};

const readWindows = () => registry.readLiveWindows(windowsDir(), isAlive);

class SessionsProvider {
  constructor(tabsBySession, plainTabs, globalState) {
    this.tabsBySession = tabsBySession;
    this.plainTabs = plainTabs;
    this.globalState = globalState;
    this.sessions = [];
    this.allSessions = [];
    this.hiddenSessions = [];
    this.groups = [];
    this.windows = [];
    this.tabPids = new Map();
    this.changed = new vscode.EventEmitter();
    this.onDidChangeTreeData = this.changed.event;
    this.statusBar = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 100);
    this.statusBar.command = 'claudeToolkit.focusMostUrgent';
  }

  refresh() {
    const now = Date.now();
    const stuckMs = vscode.workspace.getConfiguration('claudeToolkit').get('stuckMinutes', 10) * 60_000;

    this.now = now;
    this.windows = readWindows();

    const { sessions, unreadableIds } = readSessions(now, stuckMs);
    const all = status.latestPerProcess(status.latestPerTitle(status.dropEnded(sessions, isAlive)));
    const stored = this.storedHidden();

    this.allSessions = all;
    const hidden = status.pruneHidden(stored, all, unreadableIds);

    if (Object.keys(hidden).length !== Object.keys(stored).length)
      this.globalState.update(HIDDEN_SESSIONS, hidden).then(undefined, reportStorageError);

    const split = status.splitHidden(all, hidden);

    this.sessions = split.visible;
    this.hiddenSessions = split.hidden;
    this.groups = status.orderedGroups(status.groupByProject(this.sessions), this.globalState.get(SESSION_ORDER, {}));
    this.renameActivePlainTab(all);
    this.updateStatusBar();
    this.changed.fire();
  }

  async publishWindow() {
    try {
      const tabs = await Promise.all([...this.tabsBySession].map(async ([name, terminal]) => ({ name, terminal, pid: await terminal.processId })));

      this.tabPids = new Map(tabs.filter((tab) => Number.isInteger(tab.pid)).map((tab) => [tab.pid, tab.terminal]));
      registry.writeAtomically(ownWindowFile(), JSON.stringify({
        pid: process.pid,
        folder: vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? '',
        sessions: tabs.map((tab) => tab.name),
        pids: [...this.tabPids.keys()],
      }));
      this.refresh();
    } catch (error) {
      reportStorageError(error);
    }
  }

  updateStatusBar() {
    const waiting = status.waitingCount(this.sessions);

    this.statusBar.text = waiting > 0 ? `$(bell-dot) ${waiting} waiting` : '$(check) none waiting';
    this.statusBar.tooltip = waiting > 0 ? 'Show the Claude session waiting longest' : 'Open Claude sessions';
    this.statusBar.backgroundColor = waiting > 0 ? new vscode.ThemeColor('statusBarItem.warningBackground') : undefined;
    this.statusBar.show();
  }

  storedHidden() {
    return this.globalState.get(HIDDEN_SESSIONS, {});
  }

  persist(key, value) {
    this.globalState.update(key, value).then(() => this.refresh(), reportStorageError);
  }

  storeHidden(hidden) {
    this.persist(HIDDEN_SESSIONS, hidden);
  }

  storeProjectOrder(moved, target) {
    const order = this.globalState.get(SESSION_ORDER, {});
    const keys = status.mergeOrder(this.groups.map((group) => group.project), order.projects ?? []);

    this.persist(SESSION_ORDER, { ...order, projects: status.moveBefore(keys, moved, target) });
  }

  storeSessionOrder(project, moved, target) {
    const group = this.groups.find((candidate) => candidate.project === project);

    if (!group)
      return;

    const order = this.globalState.get(SESSION_ORDER, {});
    const keys = status.pruneOrderKeys(status.mergeOrder(group.sessions.map(status.sessionKey), order.sessions?.[project] ?? []), this.allSessions);

    this.persist(SESSION_ORDER, { ...order, sessions: { ...order.sessions, [project]: status.moveBefore(keys, moved, target) } });
  }

  drop(dragged, target) {
    if (!target || target.kind === 'hidden' || this.hiddenSessions.includes(target))
      return;

    if (dragged.kind === 'project' && target.sessions && target.project !== dragged.project)
      this.storeProjectOrder(dragged.project, target.project);
    else if (dragged.kind === 'session' && target.project === dragged.project)
      this.storeSessionOrder(dragged.project, dragged.key, target.sessions ? undefined : status.sessionKey(target));
  }

  move(element, step) {
    if (element.sessions) {
      const projects = this.groups.map((group) => group.project);
      const target = status.stepTarget(projects, element.project, step);

      if (target !== null)
        this.storeProjectOrder(element.project, target);

      return;
    }

    const group = this.groups.find((candidate) => candidate.project === element.project);

    if (!group)
      return;

    const key = status.sessionKey(element);
    const target = status.stepTarget(group.sessions.map(status.sessionKey), key, step);

    if (target !== null)
      this.storeSessionOrder(element.project, key, target);
  }

  resetOrder() {
    this.persist(SESSION_ORDER, {});
  }

  hide(session) {
    this.storeHidden({ ...this.storedHidden(), [session.id]: session.lastEventAt });
  }

  hideTabSessions(sessionName, pid) {
    const inTab = this.sessions.filter((candidate) => (pid !== undefined && candidate.pid === pid) || candidate.name === sessionName);

    this.storeHidden({ ...this.storedHidden(), ...Object.fromEntries(inTab.map((session) => [session.id, session.lastEventAt])) });
  }

  showAgain(session) {
    const { [session.id]: _shown, ...rest } = this.storedHidden();

    this.storeHidden(rest);
  }

  renameActivePlainTab(sessions) {
    const terminal = vscode.window.activeTerminal;

    if (!terminal || !this.plainTabs.has(terminal))
      return;

    const pid = [...this.tabPids].find(([, candidate]) => candidate === terminal)?.[0];
    const name = status.plainTabRename(terminal.name, pid, sessions);

    if (!name || vscode.window.activeTerminal !== terminal)
      return;

    vscode.commands.executeCommand('workbench.action.terminal.renameWithArg', { name }).then(undefined, (error) => {
      void vscode.window.showWarningMessage(`Claude Toolkit: could not rename the Claude tab: ${error.message}`);
    });
  }

  location(session) {
    return status.sessionLocation(session.name, process.pid, this.windows, session.pid);
  }

  showOwnTab(sessionName, pid) {
    const terminal = (pid !== undefined && this.tabPids.get(pid)) || this.tabsBySession.get(sessionName);

    if (terminal)
      terminal.show(false);
  }

  focus(session) {
    const location = this.location(session);
    const action = status.clickAction(location);

    this.lastFocusedId = session.id;

    if (action === 'show') {
      this.showOwnTab(session.name, session.pid);

      return;
    }

    if (action === 'raise') {
      writeFocusRequest(location.window.pid, session);
      void vscode.commands.executeCommand('vscode.openFolder', vscode.Uri.file(location.window.folder), { forceNewWindow: true });

      return;
    }

    void vscode.window.showInformationMessage(`${session.name} is not a toolkit tab in any VS Code window; it was started by hand.`);
  }

  focusMostUrgent() {
    const [first] = status.waitingSessions(this.sessions);

    if (first) {
      this.focus(first);

      return;
    }

    void vscode.commands.executeCommand(`${VIEW_ID}.focus`);
  }

  focusNextWaiting() {
    const next = status.nextWaiting(status.waitingSessions(this.sessions), this.lastFocusedId);

    if (next) {
      this.focus(next);

      return;
    }

    void vscode.window.showInformationMessage('No Claude session is waiting for you.');
  }

  receiveFocusRequest() {
    const file = focusFile(process.pid);
    const request = registry.readJson(file);

    fs.rmSync(file, { force: true });

    if (typeof request?.session === 'string')
      this.showOwnTab(request.session, Number.isInteger(request.pid) ? request.pid : undefined);
  }

  getTreeItem(element) {
    if (element.kind === 'hidden')
      return this.hiddenGroupItem(element);

    return element.sessions ? this.groupItem(element) : this.sessionItem(element);
  }

  hiddenGroupItem(group) {
    const item = new vscode.TreeItem(`Hidden (${group.sessions.length})`, vscode.TreeItemCollapsibleState.Collapsed);

    item.id = 'hidden';
    item.tooltip = 'Sessions you hid or whose tab you closed. Use the eye button to show one again.';
    item.iconPath = new vscode.ThemeIcon('eye-closed');

    return item;
  }

  groupItem(group) {
    const item = new vscode.TreeItem(group.project, vscode.TreeItemCollapsibleState.Expanded);

    item.id = `project:${group.project}`;
    item.contextValue = 'project';
    item.description = status.groupDescription(group);
    item.iconPath = new vscode.ThemeIcon('folder', new vscode.ThemeColor(status.STATUS[group.top.status].color));

    return item;
  }

  sessionItem(session) {
    const item = new vscode.TreeItem(session.name);
    const look = status.STATUS[session.status];
    const where = status.locationLabel(this.location(session));

    item.id = `session:${session.id}`;
    item.description = status.cardDescription(session, this.now);
    item.iconPath = new vscode.ThemeIcon('circle-filled', new vscode.ThemeColor(look.color));
    item.tooltip = [look.label, where, session.last].filter(Boolean).join('\n');
    item.contextValue = this.hiddenSessions.includes(session) ? 'hiddenSession' : 'session';
    item.command = { command: 'claudeToolkit.focusSession', title: 'Show tab', arguments: [session] };

    return item;
  }

  getChildren(element) {
    if (element)
      return element.sessions;

    return this.hiddenSessions.length > 0 ? [...this.groups, { kind: 'hidden', sessions: this.hiddenSessions }] : this.groups;
  }
}

const reportStorageError = (error) => {
  void vscode.window.showErrorMessage(`Claude Toolkit: could not save the session view state: ${error.message}`);
};

const dragAndDrop = (provider) => ({
  dragMimeTypes: [DRAG_MIME],
  dropMimeTypes: [DRAG_MIME],
  handleDrag: ([element], dataTransfer) => {
    if (!element || element.kind === 'hidden' || provider.hiddenSessions.includes(element))
      return;

    const dragged = element.sessions
      ? { kind: 'project', project: element.project }
      : { kind: 'session', project: element.project, key: status.sessionKey(element) };

    dataTransfer.set(DRAG_MIME, new vscode.DataTransferItem(JSON.stringify(dragged)));
  },
  handleDrop: async (target, dataTransfer) => {
    const item = dataTransfer.get(DRAG_MIME);

    if (item)
      provider.drop(JSON.parse(await item.asString()), target);
  },
});

const watch = (directory, pattern, onEvent) => {
  fs.mkdirSync(directory, { recursive: true });

  const watcher = vscode.workspace.createFileSystemWatcher(new vscode.RelativePattern(vscode.Uri.file(directory), pattern));

  watcher.onDidCreate(onEvent);
  watcher.onDidChange(onEvent);
  watcher.onDidDelete(onEvent);

  return watcher;
};

const registerSessionsView = (context, tabsBySession, plainTabs) => {
  const provider = new SessionsProvider(tabsBySession, plainTabs, context.globalState);

  const refresh = () => provider.refresh();
  const timer = setInterval(refresh, REFRESH_MS);

  context.subscriptions.push(
    provider.statusBar,
    watch(sessionsDir(), '*.jsonl', refresh),
    watch(windowsDir(), '*.json', refresh),
    watch(focusDir(), `${process.pid}.json`, () => provider.receiveFocusRequest()),
    { dispose: () => clearInterval(timer) },
    { dispose: () => fs.rmSync(ownWindowFile(), { force: true }) },
    vscode.window.createTreeView(VIEW_ID, { treeDataProvider: provider, dragAndDropController: dragAndDrop(provider) }),
    vscode.commands.registerCommand('claudeToolkit.resetOrder', () => provider.resetOrder()),
    vscode.commands.registerCommand('claudeToolkit.moveUp', (element) => provider.move(element, -1)),
    vscode.commands.registerCommand('claudeToolkit.moveDown', (element) => provider.move(element, 1)),
    vscode.commands.registerCommand('claudeToolkit.focusSession', (session) => provider.focus(session)),
    vscode.commands.registerCommand('claudeToolkit.hideSession', (session) => provider.hide(session)),
    vscode.commands.registerCommand('claudeToolkit.showSessionAgain', (session) => provider.showAgain(session)),
    vscode.commands.registerCommand('claudeToolkit.focusMostUrgent', () => provider.focusMostUrgent()),
    vscode.commands.registerCommand('claudeToolkit.nextWaiting', () => provider.focusNextWaiting()),
    vscode.window.onDidChangeActiveTerminal(refresh),
    vscode.window.onDidCloseTerminal((terminal) => {
      for (const [sessionName, tab] of tabsBySession) {
        if (tab !== terminal)
          continue;

        const pid = [...provider.tabPids].find(([, candidate]) => candidate === terminal)?.[0];

        tabsBySession.delete(sessionName);
        provider.hideTabSessions(sessionName, pid);
        void provider.publishWindow();
      }
    }),
  );

  void provider.publishWindow();

  return { publishWindow: () => provider.publishWindow() };
};

module.exports = { registerSessionsView };

const STATUS = {
  permission: { rank: 0, label: 'waiting for permission', color: 'charts.red' },
  question: { rank: 0, label: 'waiting for your answer', color: 'charts.red' },
  stuck: { rank: 1, label: 'possibly stuck', color: 'charts.purple' },
  finished: { rank: 2, label: 'finished, needs review', color: 'charts.yellow' },
  working: { rank: 3, label: 'working', color: 'charts.green' },
  idle: { rank: 4, label: 'idle', color: 'disabledForeground' },
};

const WAITING = new Set(['permission', 'question']);

const parseEvents = (text) => text
  .split('\n')
  .filter((line) => line.trim())
  .flatMap((line) => {
    try {
      return [JSON.parse(line)];
    } catch {
      return [];
    }
  })
  .filter((event) => typeof event?.t === 'number' && typeof event.event === 'string')
  .sort((first, second) => first.t - second.t);

const belongsToCurrentTurn = (event, state) => {
  if (!event.promptId)
    return true;

  if (state.closedPrompts.has(event.promptId))
    return false;

  return !state.currentPrompt || event.promptId === state.currentPrompt;
};

const setStatus = (state, status, t) => {
  if (state.status !== status)
    state.since = t;

  state.status = status;
};

const applyEvent = (state, event) => {
  if (event.title)
    state.name = event.title;

  if (event.folder)
    state.folder ??= event.folder;

  if (Number.isInteger(event.pid))
    state.pid = event.pid;

  if (event.event === 'SessionStart') {
    state.status ??= 'idle';
    state.since ??= event.t;

    return;
  }

  if (event.event === 'UserPromptSubmit') {
    state.currentPrompt = event.promptId;
    state.tool = undefined;
    setStatus(state, 'working', event.t);

    return;
  }

  if (!belongsToCurrentTurn(event, state))
    return;

  state.currentPrompt ??= event.promptId;

  if (event.event === 'PreToolUse' && event.tool === 'AskUserQuestion') {
    setStatus(state, 'question', event.t);

    return;
  }

  if (event.event === 'PermissionRequest') {
    state.tool = event.tool;
    setStatus(state, 'permission', event.t);

    return;
  }

  if (event.event === 'PostToolUse' || event.event === 'PostToolUseFailure') {
    state.tool = event.tool;
    setStatus(state, 'working', event.t);

    return;
  }

  if (event.event === 'Stop') {
    state.closedPrompts.add(event.promptId);
    state.tool = undefined;
    state.last = event.last;
    setStatus(state, event.asks ? 'question' : 'finished', event.t);
  }
};

const sessionState = ({ id, events, now, stuckMs }) => {
  const state = { id, closedPrompts: new Set() };
  const ordered = [...events].sort((first, second) => first.t - second.t);

  for (const event of ordered)
    applyEvent(state, event);

  const lastEventAt = ordered.at(-1)?.t;
  const stuck = state.status === 'working' && lastEventAt !== undefined && now - lastEventAt > stuckMs;

  return {
    id,
    titled: Boolean(state.name),
    pid: state.pid,
    name: state.name || state.folder || id.slice(0, 8),
    project: state.folder || 'unknown project',
    status: stuck ? 'stuck' : state.status ?? 'idle',
    since: stuck ? lastEventAt : state.since ?? lastEventAt ?? now,
    lastEventAt: lastEventAt ?? now,
    tool: state.tool,
    last: state.last ?? '',
  };
};

const byUrgency = (first, second) => {
  const rank = STATUS[first.status].rank - STATUS[second.status].rank;

  return rank !== 0 ? rank : first.since - second.since;
};

const formatDuration = (milliseconds) => {
  const seconds = Math.max(0, Math.floor(milliseconds / 1000));

  if (seconds < 60)
    return `${seconds}s`;

  const minutes = Math.floor(seconds / 60);

  if (minutes < 60)
    return `${minutes}m`;

  return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
};

const cardDescription = (session, now) => {
  const parts = [STATUS[session.status].label];

  if (session.tool && session.status === 'permission')
    parts.push(session.tool);

  if (session.tool && (session.status === 'working' || session.status === 'stuck'))
    parts.push(`after ${session.tool}`);

  parts.push(formatDuration(now - session.since));

  return parts.join(' · ');
};

const waitingCount = (sessions) => sessions.filter((session) => WAITING.has(session.status)).length;

const isVisible = (session, hiddenAt) => hiddenAt === undefined || session.lastEventAt > hiddenAt;

const applyOrder = (items, keys, keyOf, fallback) => {
  const position = new Map(keys.map((key, index) => [key, index]));
  const placed = items.filter((item) => position.has(keyOf(item))).sort((first, second) => position.get(keyOf(first)) - position.get(keyOf(second)));
  const rest = items.filter((item) => !position.has(keyOf(item))).sort(fallback);

  return [...placed, ...rest];
};

const moveBefore = (keys, moved, target) => {
  const without = keys.filter((key) => key !== moved);
  const index = target === undefined ? -1 : without.indexOf(target);

  return index === -1 ? [...without, moved] : [...without.slice(0, index), moved, ...without.slice(index)];
};

const mergeOrder = (displayed, stored) => {
  const merged = [...displayed];

  stored.forEach((key, index) => {
    if (merged.includes(key))
      return;

    const predecessor = stored.slice(0, index).reverse().find((candidate) => merged.includes(candidate));

    merged.splice(predecessor === undefined ? 0 : merged.indexOf(predecessor) + 1, 0, key);
  });

  return merged;
};

const stepTarget = (keys, key, step) => {
  const index = keys.indexOf(key);
  const destination = index + step;

  if (index === -1 || destination < 0 || destination >= keys.length)
    return null;

  return step < 0 ? keys[destination] : keys[destination + 1];
};

const sessionKey = (session) => (session.titled ? session.name : `id:${session.id}`);

const orderedGroups = (groups, order) => applyOrder(
  groups.map((group) => ({ ...group, sessions: applyOrder(group.sessions, order.sessions?.[group.project] ?? [], sessionKey, byUrgency) })),
  order.projects ?? [],
  (group) => group.project,
  byGroupUrgency,
);

const splitHidden = (sessions, hidden) => ({
  visible: sessions.filter((session) => isVisible(session, hidden[session.id])),
  hidden: sessions
    .filter((session) => !isVisible(session, hidden[session.id]))
    .sort((first, second) => second.lastEventAt - first.lastEventAt),
});

const pruneHidden = (hidden, sessions, unreadableIds = new Set()) => Object.fromEntries([
  ...sessions
    .filter((session) => hidden[session.id] !== undefined && !isVisible(session, hidden[session.id]))
    .map((session) => [session.id, hidden[session.id]]),
  ...[...unreadableIds].filter((id) => hidden[id] !== undefined).map((id) => [id, hidden[id]]),
]);

const latestPerTitle = (sessions) => {
  const latest = new Map();

  for (const session of sessions.filter((candidate) => candidate.titled)) {
    const current = latest.get(session.name);

    if (!current || session.lastEventAt > current.lastEventAt)
      latest.set(session.name, session);
  }

  return sessions.filter((session) => !session.titled || latest.get(session.name) === session);
};

const byGroupUrgency = (first, second) => byUrgency(first.top, second.top) || first.project.localeCompare(second.project);

const dropEnded = (sessions, isAlive) => sessions.filter((session) => session.pid === undefined || isAlive(session.pid));

const pruneOrderKeys = (keys, sessions) => {
  const ids = new Set(sessions.map((session) => `id:${session.id}`));

  return keys.filter((key) => !key.startsWith('id:') || ids.has(key));
};

const plainTabRename = (tabName, tabPid, sessions) => {
  if (tabPid === undefined)
    return null;

  const session = sessions.find((candidate) => candidate.pid === tabPid);

  return session && session.name !== tabName ? session.name : null;
};

const latestPerProcess = (sessions) => {
  const latest = new Map();

  for (const session of sessions.filter((candidate) => candidate.pid !== undefined)) {
    const current = latest.get(session.pid);

    if (!current || session.lastEventAt > current.lastEventAt)
      latest.set(session.pid, session);
  }

  return sessions.filter((session) => session.pid === undefined || latest.get(session.pid) === session);
};

const groupByProject = (sessions) => {
  const groups = new Map();

  for (const session of [...sessions].sort(byUrgency))
    groups.set(session.project, [...(groups.get(session.project) ?? []), session]);

  return [...groups.entries()]
    .map(([project, members]) => ({ project, sessions: members, top: members[0], waiting: waitingCount(members) }))
    .sort(byGroupUrgency);
};

const groupDescription = (group) => {
  const count = `${group.sessions.length} session${group.sessions.length === 1 ? '' : 's'}`;

  return group.waiting > 0 ? `${group.waiting} waiting · ${count}` : count;
};

const waitingSessions = (sessions) => sessions.filter((session) => WAITING.has(session.status)).sort(byUrgency);

const nextWaiting = (waiting, lastFocusedId) => {
  if (waiting.length === 0)
    return undefined;

  const index = waiting.findIndex((session) => session.id === lastFocusedId);

  return waiting[(index + 1) % waiting.length];
};

const clickAction = (location) => {
  if (location.kind === 'here')
    return 'show';

  return location.kind === 'other' ? 'raise' : 'message';
};

const liveWindows = (entries, isAlive) => entries.filter((entry) =>
  Number.isInteger(entry?.pid)
  && typeof entry.folder === 'string'
  && Array.isArray(entry.sessions)
  && isAlive(entry.pid));

const holdsProcess = (entry, pid) => pid !== undefined && Array.isArray(entry.pids) && entry.pids.includes(pid);

const sessionLocation = (sessionName, ownPid, windows, sessionPid) => {
  const holder = windows.find((entry) => holdsProcess(entry, sessionPid))
    ?? windows.find((entry) => entry.sessions.includes(sessionName));

  if (!holder)
    return { kind: 'none' };

  return holder.pid === ownPid ? { kind: 'here', window: holder } : { kind: 'other', window: holder };
};

const locationLabel = (location) => {
  if (location.kind === 'here')
    return 'in this window';

  if (location.kind === 'other')
    return `in window ${location.window.folder.split(/[\\/]/).filter(Boolean).at(-1) ?? location.window.folder}`;

  return 'not in a toolkit tab';
};

module.exports = {
  STATUS,
  byUrgency,
  cardDescription,
  clickAction,
  nextWaiting,
  waitingSessions,
  formatDuration,
  groupByProject,
  groupDescription,
  isVisible,
  dropEnded,
  latestPerProcess,
  plainTabRename,
  pruneOrderKeys,
  latestPerTitle,
  liveWindows,
  locationLabel,
  applyOrder,
  mergeOrder,
  moveBefore,
  sessionKey,
  stepTarget,
  orderedGroups,
  parseEvents,
  pruneHidden,
  sessionLocation,
  splitHidden,
  sessionState,
  waitingCount,
};
